#!/usr/bin/env python3
"""
Round 216o (culprits-tiles-more), 16 October 2026.

- scripts/gem_ownership.py: Global Energy Monitor's Global Energy Ownership
  Tracker (CC BY 4.0), read from gem/ownership/download/ (the workbook, or a
  zip of its sheets as compressed CSVs), every sheet, row and column; writes
  gem/ownership/parents.geojson, entities.geojson and build.json. Tried here
  on the September 2026 release: 11,435 parents (10,935 placed), 27,707
  entities (27,011 placed); the rest have no country.
- gem/ownership/download was an empty file; it becomes a folder (with a
  README) so the download can go in it.

Then upload the zip to gem/ownership/download/ and run refresh with gem_ownership.
Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/gem_ownership.py': '', 'gem/ownership/download/README.md': 'VXBsb2FkIEdsb2JhbCBFbmVyZ3kgTW9uaXRvcidzIEdsb2JhbCBFbmVyZ3kgT3duZXJzaGlwIFRyYWNrZXIgaGVyZTogdGhlIHdvcmtib29rIGFzIGl0IGNvbWVzLCBvciBhIHppcCBvZiBpdHMgc2hlZXRzIGFzIGNvbXByZXNzZWQgQ1NWcyAodGhlIHdvcmtib29rIGlzIHRvbyBiaWcgZm9yIEdpdEh1YidzIHdlYiB1cGxvYWQpLgo='}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round216o_tiles: run from the culprits-tiles-more repository root")
    d = pathlib.Path("gem/ownership/download")
    if d.is_file():
        d.unlink()
        print("round216o_tiles: gem/ownership/download was a file; it is now a folder")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round216o_tiles: wrote {path}")
    if not changed:
        print("round216o_tiles: already applied")


if __name__ == "__main__":
    main()
